CREATE TABLE IF NOT EXISTS minutes (id INT PRIMARY KEY AUTO_INCREMENT, meetingId INT NOT NULL, content LONGTEXT, status ENUM('draft', 'approved', 'published') DEFAULT 'draft', approvedBy INT, approvedAt DATETIME, createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_meeting_minutes (meetingId));
CREATE TABLE IF NOT EXISTS actionItems (id INT PRIMARY KEY AUTO_INCREMENT, meetingId INT NOT NULL, minutesId INT, title VARCHAR(255) NOT NULL, description TEXT, assignedTo INT, dueDate DATETIME, status ENUM('open', 'inProgress', 'completed', 'cancelled') DEFAULT 'open', priority ENUM('low', 'medium', 'high') DEFAULT 'medium', createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_meeting_action (meetingId));
CREATE TABLE IF NOT EXISTS assessments (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, assessmentType VARCHAR(100), status ENUM('draft', 'active', 'closed', 'archived') DEFAULT 'draft', createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_assessment (organizationId));

